  str_season_maze_s1_help_disc_101 = "과거의 꿈의 세계 속 불안정 요소는 여전히 이 세계에 잠재되어 있으며, 현실을 뒤집을 기회만을 노리고 있습니다. 계몽자의 도움으로 꿈의 세계로 돌아온 조종사는 이제 다양한 스타일의 탐색 활동을 경험하게 됩니다. 꿈의 세계에서의 실력을 지속적으로 향상시키면 「얼티밋 드림 이터」를 쓰러트리고, 꿈의 세계 에너지의 균형을 회복할 수 있을 것입니다.",
  str_season_maze_s1_help_disc_102 = "조종사는 계몽자를 이끌고 「드림카드」의 힘을 빌려, 다른 「꿈의 영역」으로 이동해서 「꿈의 영역」의 사건을 발동시키게 됩니다. 탐색 과정에서 조종사는 오로리안을 소환하고 「꿈의 장비」, 판타즘 스톤 및 각종 「꿈의 영역」 자원을 수집해서 자신의 실력을 향상시킬 수 있습니다. 마지막으로 「꿈을 먹는 그림자」와 「얼티밋 드림 이터」 도전에 성공하면 꿈의 세계 탐색을 마치고 풍성한 보상을 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_201 = "계몽자는 꿈의 세계 속 조종사의 행동을 평가하고, 상응하는 「꿈의 심도」를 자동으로 기록합니다. 「꿈의 심도」를 충분히 누적하면 상응하는 보상을 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_202 = "탐색이 끝날 때마다 계몽자는 「꿈의 세계 단계」와 「탐색 진행도」따라 상응하는 「꿈의 심도」를 기록합니다. 누적된 「꿈의 심도」가 일정 수준에 도달하면 상응하는 보상을 획득할 수 있습니다. 또한 「꿈의 세계 임무」를 완수하면 추가로 「꿈의 심도」를 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_203 = "누적된 「꿈의 심도」가 일정 수준에 도달하면 상응하는 보상을 획득할 수 있습니다. 일정 시간마다 더 많은 보상 단계가 개방됩니다.",
  str_season_maze_s1_help_disc_204 = "꿈의 세계에는 다양한 「꿈의 세계 임무」가 있습니다. 「꿈의 세계 임무」를 완수하면 추가로 「꿈의 심도」를 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_301 = "꿈의 세계에는 여러 단계가 있습니다. 꿈의 세계의 단계가 높을수록 도전이 더 어려워지며, 도전 성공 후 획득하는 「꿈의 심도」도 더 많아집니다. 꿈의 세계 단계 화면에서 현재 단계 내 활동하는 「얼티밋 드림 이터」를 확인할 수 있으며, 「얼티밋 드림 이터」의 정보에 따라 탐색 전략을 결정해야 합니다.",
  str_season_maze_s1_help_disc_302 = "초기 단계는 「꿈의 세계 1단계」이며, 이전 단계를 완료해야만 후속 단계를 개방할 수 있습니다. 일부 단계는 시간이 지나면 개방됩니다. 「꿈의 세계 3단계」가 개방되면 「판타즘 스톤」 시스템이 함께 개방되어 탐색을 돕습니다.",
  str_season_maze_s1_help_disc_303 = "꿈의 세계에 진입할 때에는 반드시 4명의 오로리안을 선발해 초기 편대에 합류시켜야만 탐색을 시작할 수 있습니다. 편대의 오로리안들은 꿈의 세계 바깥의 오로리안의 돌파 레벨을 계승하지만, 레벨 및 나머지 육성 상태는 계승하지 않습니다.",
  str_season_maze_s1_help_disc_401 = "탐색 과정에서 조종사는 자신을 움직여 계몽자와 함께 탐색을 진행할 수 있습니다.",
  str_season_maze_s1_help_disc_402 = "계몽자는 꿈의 에너지 파동 상황에 근거해 「꿈의 세계」를 서로 다른 「꿈의 영역」으로 구분합니다. 조종사는 「꿈의 영역」 사이에서만 걸을 수 있으며, 각 「꿈의 영역」은 저마다 다른 사건을 발동할 것입니다.",
  str_season_maze_s1_help_disc_403 = "조종사는 「드림카드」의 힘을 빌려 서로 다른 꿈의 영역 사이를 이동할 수 있습니다. 「드림카드」의 「행동 걸음 수」는 조종사가 이동할 수 있는 「꿈의 영역」의 수량을 결정하며, 일부 「드림카드」는 추가 자원이나 특수 효과를 동반하기도 합니다. 턴이 시작될 때마다 계몽자는 카드덱에서 일정 수량의 「드림카드」를 뽑으며, 조종사는 이중에서 한 장을 내거나 직접 화면으로 끌어당겨 해당 「드림카드」의 효과를 실행할 수 있습니다.",
  str_season_maze_s1_help_disc_404 = "조종사는 꿈의 세계에서 다양한 자원을 획득할 수 있습니다. 「꿈의 입자」는 각종 아이템을 구매할 수 있고, 「꿈의 깨달음」은 「탐색 레벨」을 높이며, 「입자 수확도」는 턴마다 획득하는 「꿈의 입자」의 수를 높이고, 「공명」은 조종사가 꿈의 세계에 탐색을 안전하게 진행할 수 있도록 보장합니다.",
  str_season_maze_s1_help_disc_405 = "「가방」에서는 이번 탐색 과정 중 이미 편대에 합류한 오로리안, 획득한 「꿈의 장비」와 카드덱에 추가된 「드림카드」를 확인할 수 있습니다.",
  str_season_maze_s1_help_disc_406 = "꿈의 세계의 원래 주인이 남긴 기억과 감정은 꿈의 에너지에 의해 겹겹이 쌓여 「판타즘 스톤」을 형성합니다. 이곳에서는 이번 탐색에서 획득한 「판타즘 스톤」을 확인할 수 있고, 조립 및 합성 등의 작업을 진행할 수 있습니다.",
  str_season_maze_s1_help_disc_407 = "「꿈을 먹는 그림자」는 일정 턴 후에 조종사를 습격할 것입니다. 「꿈을 먹는 그림자」를 이겨야만 꿈의 세계를 계속 탐색할 수 있습니다. 「얼티밋 드림 이터」는 마지막 「꿈을 먹는 그림자」입니다. 「얼티밋 드림 이터」를 이기면 이번 탐색을 끝낼 수 있습니다. 꿈의 세계의 단계 및 탐색 진행도에 따라 상응하는 「꿈의 심도」를 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_408 = "이곳에서는 이번 전투의 전장 특성과 적 정보를 확인할 수 있으며, 조종사는 해당 정보를 토대로 전투 전략을 조정할 수 있습니다. 도전에 성공하면 상응하는 보상을 획득할 수 있으며, 실패 시 공명을 소모해 재도전할 수 있습니다.",
  str_season_maze_s1_help_disc_409 = "탐색 과정에서 얻은 「꿈의 깨달음」은 「탐색 레벨」을 높일 수 있습니다. 「탐색 레벨」이 높아지면 오로리안 및 장비 레벨을 높이고, 새로운 「드림카드」와 「꿈의 도구」를 획득해 꿈의 세계 탐색을 도울 수 있습니다.",
  str_season_maze_s1_help_disc_501 = "「위험 영역」에 진입해 적과 교전하고, 승리 시 「꿈의 장비」 1개를 선택할 수 있습니다.",
  str_season_maze_s1_help_disc_502 = "「미지의 영역」 진입 시 랜덤으로 사건이 발생하며, 일부 사건에서는 3장의 「드림카드」를 뽑아 점수의 합을 계산하고 보상 획득 여부를 판정하게 됩니다.",
  str_season_maze_s1_help_disc_503 = "「자원 영역」에 진입 시 대응하는 유형의 자원 보상을 획득할 수 있습니다. 자원에는 「꿈의 입자」, 「꿈의 깨달음」, 「판타즘 스톤」이 포함됩니다. 해당 영역에 들어가기 전 「행동 걸음 수」가 많을수록 보상이 증가합니다.",
  str_season_maze_s1_help_disc_504 = "「미개척 영역」 진입 시 오로리안을 파견해 임무를 수행하고, 지속 수익을 획득할 수 있습니다. 파견 기간 중 해당 오로리안은 전투에 참가할 수 없으며, 5턴 후 자동으로 복귀합니다.",
  str_season_maze_s1_help_disc_505 = "「보물 영역」 진입 시 여러 보상 중 하나를 선택해 획득할 수 있습니다.",
  str_season_maze_s1_help_disc_506 = "「영역 터널」 진입 시 꿈을 먹는 그림자의 습격이 1턴 지연됩니다.",
  str_season_maze_s1_help_disc_507 = "「공백 영역」 진입 시 아무 효과도 발동하지 않습니다.",
  str_season_maze_s1_help_disc_508 = "「카드 영역」에서는 꿈의 입자를 소모해 기존 드림카드를 재설정 및 삭제할 수 있습니다.",
  str_season_maze_s1_help_disc_509 = "「순환 영역」에서는 다른 플레이어와 다른 유형의 판타즘 스톤을 교환할 수 있습니다.",
  str_season_maze_s1_help_disc_510 = "조종사는 「안전 영역」에서 휴식을 취할 수 있고, 오로리안 소환·물품 구매·오로리안 치료 및 부활 등을 진행해 전력을 강화할 수 있습니다. 「꿈의 입자」를 「꿈의 용광로」에 저장하면 향후 도전을 위해 더 강력한 아이템을 개방할 수 있습니다.",
  str_season_maze_s1_help_disc_601 = "조종사는 오로리안을 편대에 추가할 수 있습니다. 편대의 오로리안들은 꿈의 세계 바깥의 오로리안의 돌파 레벨을 계승하지만, 레벨 및 나머지 육성 상태는 계승하지 않습니다. 「탐색 레벨」을 높이면 꿈의 세계 속 오로리안 레벨과 장비 레벨이 증가합니다.",
  str_season_maze_s1_help_disc_602 = "「꿈의 장비」는 기나긴 시간 속에서 용감하게 꿈의 세계를 탐험했던 드림 워커들이 잃어버린 귀중한 지식과 진귀한 유물들입니다. 「꿈의 장비」는 다양한 효과를 발동해 조종사의 꿈의 세계 탐색을 도울 수 있습니다.",
  str_season_maze_s1_help_disc_603 = "조종사는 「드림카드」의 힘을 빌려 서로 다른 꿈의 영역 사이를 이동할 수 있습니다. 「드림카드」의 「행동 걸음 수」는 조종사가 이동할 수 있는 「꿈의 영역」의 수량을 결정하며, 일부 「드림카드」는 「꿈의 입자」, 「입자 수확도」, 「꿈의 깨달음」, 「공명」 등 추가 자원이나 특수 효과를 동반하기도 합니다.",
  str_season_maze_s1_help_disc_604 = "꿈의 세계의 원래 주인이 남긴 기억과 감정은 꿈의 에너지에 의해 겹겹이 쌓여 「판타즘 스톤」을 형성합니다. 「판타즘 스톤」은 꿈의 세계 속 조종사의 전투력을 높일 수 있습니다. 「꿈을 먹는 그림자」에게 빼앗기지 않도록 조심하세요.",
  str_season_maze_s1_help_disc_605 = "「꿈의 도구」는 꿈의 세계 속 에너지가 현실의 물건에 대한 「기억」을 토대로 우연히 풍화되어 만들어진 물건들입니다. 「꿈의 도구」마다 효과가 다르며, 적절한 시기에 「꿈의 도구」를 사용하면 탐색에 도움이 될 것입니다.",
  str_season_maze_s1_guide_warn_90010101 = "알림, 꿈의 세계가 교차하는 공간에 성공적으로 도착했습니다. 이곳에서 아버지는 그동안 겪었던 수많은 꿈의 세계를 찾을 수 있을 것입니다. 계몽자의 안내에 따라 다양한 탐색 활동을 진행하고 실력을 키워보세요. 「얼티밋 드림 이터」를 타도하고 꿈의 에너지의 균형을 되찾아야 합니다.",
  str_season_maze_s1_guide_warn_90010102 = "알림, 여기를 누르면 꿈의 세계에 착륙해 탐험을 시작할 수 있습니다.",
  str_season_maze_s1_guide_warn_90010103 = "알림, 탐색이 끝날 때마다 아버지의 꿈의 세계 속 행동은 평가를 받고, 상응하는 「꿈의 심도」를 획득합니다. 누적된 「꿈의 심도」가 일정 수준에 도달하면 탐색 보상을 획득할 수 있습니다.",
